/**
 * Mostly used as a facade so all controllers have a single point of entry
 *
 * @author Michael Isvy
 * @author Vitaliy Fedoriv
 */
public interface ClinicService {

	Pet findPetById(int id) throws DataAccessException;
	Collection<Pet> findAllPets() throws DataAccessException;
    Page<Pet> findPets(Pageable pageable) throws DataAccessException;
	void savePet(Pet pet) throws DataAccessException;
	void deletePet(Pet pet) throws DataAccessException;

	Collection<Visit> findVisitsByPetId(int petId);
	Visit findVisitById(int visitId) throws DataAccessException;
	Collection<Visit> findAllVisits() throws DataAccessException;
	void saveVisit(Visit visit) throws DataAccessException;
	void deleteVisit(Visit visit) throws DataAccessException;
	Vet findVetById(int id) throws DataAccessException;
	Collection<Vet> findVets() throws DataAccessException;
	Collection<Vet> findAllVets() throws DataAccessException;
	void saveVet(Vet vet) throws DataAccessException;
	void deleteVet(Vet vet) throws DataAccessException;
	Owner findOwnerById(int id) throws DataAccessException;
	Collection<Owner> findAllOwners() throws DataAccessException;
	Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException;
	void saveOwner(Owner owner) throws DataAccessException;
	void deleteOwner(Owner owner) throws DataAccessException;

	/**
	 * Returns {@code true} if any owner already uses the given telephone number. The argument and every
	 * stored value are compared in their normalized (digits-only) form, so differently formatted but
	 * equivalent numbers collide. Enforces the "unique telephone" invariant for every owner write path.
	 *
	 * @param telephone the telephone number to look for (in any format)
	 * @return whether the normalized telephone is already in use by an owner
	 */
	boolean isTelephoneInUse(String telephone) throws DataAccessException;

	/**
	 * Returns {@code true} if another owner already has both the given last name and address. The
	 * last name and address are compared case-insensitively with runs of whitespace collapsed to a
	 * single space (and surrounding whitespace trimmed), so differently cased or spaced but
	 * equivalent values collide. Enforces the "one household per last name + address" invariant on
	 * owner creation.
	 *
	 * @param lastName the last name to look for
	 * @param address the address to look for
	 * @return whether an existing owner shares the same normalized last name and address
	 */
	boolean isHouseholdInUse(String lastName, String address) throws DataAccessException;

	/**
	 * Returns a stable, shared household identifier derived from the given last name and address.
	 * The inputs are normalized the same way as {@link #isHouseholdInUse(String, String)}
	 * (trimmed, runs of whitespace collapsed, lower-cased) before hashing, so every owner in the
	 * same household (same last name + address) deterministically receives the identical value.
	 *
	 * @param lastName the last name of the household
	 * @param address the address of the household
	 * @return a stable identifier shared by all owners of the household
	 */
	String householdIdFor(String lastName, String address) throws DataAccessException;

	/**
	 * Returns {@code true} if the given city has already reached its owner capacity, i.e. it already
	 * contains 50 or more owners (compared case-insensitively, the same way the per-city customer-code
	 * sequence counts them). Enforces the "at most 50 owners per city" invariant on owner creation.
	 *
	 * @param city the city to check
	 * @return whether the city already contains 50 or more owners
	 */
	boolean isCityAtCapacity(String city) throws DataAccessException;

	/**
	 * Returns {@code true} if 100 or more owners have already been registered today, i.e. the number
	 * of owners whose {@code registrationDate} equals the server's current date has reached the daily
	 * create limit. Enforces the "at most 100 owners created per day" invariant on owner creation.
	 *
	 * @return whether 100 or more owners already carry today's registration date
	 */
	boolean isDailyRegistrationAtCapacity() throws DataAccessException;

	/**
	 * Returns {@code true} when more than 80 owners have already been created today, i.e. the
	 * number of owners whose {@code registrationDate} equals the server's current date exceeds
	 * the bulk-signup threshold. Drives the read-only {@code bulkSignupWarning} response flag.
	 *
	 * @return whether more than 80 owners already carry today's registration date
	 */
	boolean isBulkSignupDay() throws DataAccessException;

	Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException;

	PetType findPetTypeById(int petTypeId);
	Collection<PetType> findAllPetTypes() throws DataAccessException;
	Collection<PetType> findPetTypes() throws DataAccessException;
	void savePetType(PetType petType) throws DataAccessException;
	void deletePetType(PetType petType) throws DataAccessException;
	Specialty findSpecialtyById(int specialtyId);
	Collection<Specialty> findAllSpecialties() throws DataAccessException;
	void saveSpecialty(Specialty specialty) throws DataAccessException;
	void deleteSpecialty(Specialty specialty) throws DataAccessException;

    List<Specialty> findSpecialtiesByNameIn(Set<String> names) throws DataAccessException;
}

